{"command": "cat > /workspace/run.go <<'GOEOF'
package main

import (
	"encoding/json"
	"fmt"
	"log"
	"os"
	"path/filepath"
	"strings"
)

func debugLog(format string, args ...interface{}) {
	if *flag_debug {
		log.Printf(format, args...)
	}
}
func errorLog(format string, args ...interface{}) {
	log.Printf(format, args...)
}

type dbConfig struct {
	Driver string
	Dsn    string
}

type configFile struct {
	Db string
	Database map[string]dbConfig
	Order []string // preserve file order
}

func loadConfig(path string, isExplicit bool) (*configFile, string, error) {
	// returns config, selectedDbName?, error?
	// For explicit missing: return error "no file"
	// For explicit bad json: return error "config error: ..."
	// For default missing: return empty config, no error (but debug log configOpen)
	var cfgPath string
	if isExplicit {
		cfgPath = path
	} else {
		// default path
		home := os.Getenv("HOME")
		if home == "" {
			home = "/home/agent"
		}
		cfgPath = filepath.Join(home, ".config", "trdsql", "config.json")
	}
	data, err := os.ReadFile(cfgPath)
	if err != nil {
		if isExplicit {
			debugLog("configOpen: open %s: no such file or directory", cfgPath)
			return nil, "", fmt.Errorf("[%s]no file", cfgPath)
		} else {
			debugLog("configOpen: open %s: no such file or directory", cfgPath)
			return &configFile{}, "", nil
		}
	}
	// file exists
	if isExplicit || *flag_debug {
		// for explicit, debug log "config found" only when debug? Actually observed:
		// explicit without debug: no "config found", only ERROR on failure, nothing on success?
		// explicit with debug: "config found" always (even on success or bad json)
		// default with debug? default missing already logged configOpen, default exists? need to handle
		// For default exists (if file exists), what log? Probably "config found" with debug?
		// We'll log "config found" when debug and file exists
		if *flag_debug {
			// use log.Printf directly to ensure it shows even when? debugLog already checks flag
			log.Printf("config found: %s", cfgPath)
		}
	} else {
		// default without debug, file exists? No log? Probably no log
	}
	// parse JSON, preserving order for database
	cfg := &configFile{}
	// Use generic map to parse
	var raw map[string]json.RawMessage
	if err := json.Unmarshal(data, &raw); err != nil {
		return nil, "", fmt.Errorf("[%s]config error: %s", cfgPath, err.Error())
	}
	if v, ok := raw["db"]; ok {
		var s string
		if err := json.Unmarshal(v, &s); err != nil {
			return nil, "", fmt.Errorf("[%s]config error: %s", cfgPath, err.Error())
		}
		cfg.Db = s
	}
	if v, ok := raw["database"]; ok {
		// need to get order: parse raw database object in order
		// Use decoder to get order
		order, m, err := parseDatabaseOrdered(v)
		if err != nil {
			return nil, "", fmt.Errorf("[%s]config error: %s", cfgPath, err.Error())
		}
		cfg.Database = m
		cfg.Order = order
	}
	return cfg, cfgPath, nil
}

func parseDatabaseOrdered(raw json.RawMessage) ([]string, map[string]dbConfig, error) {
	// raw is JSON object for database
	// Use decoder to preserve order
	dec := json.NewDecoder(strings.NewReader(string(raw)))
	tok, err := dec.Token()
	if err != nil {
		return nil, nil, err
	}
	if tok != json.Delim('{') {
		return nil, nil, fmt.Errorf("expected object")
	}
	var order []string
	m := make(map[string]dbConfig)
	for dec.More() {
		tok, err := dec.Token()
		if err != nil {
			return nil, nil, err
		}
		key, ok := tok.(string)
		if !ok {
			return nil, nil, fmt.Errorf("expected string key")
		}
		var dc dbConfig
		if err := dec.Decode(&dc); err != nil {
			return nil, nil, err
		}
		order = append(order, key)
		m[key] = dc
	}
	// consume closing }
	_, err = dec.Token()
	if err != nil {
		return nil, nil, err
	}
	return order, m, nil
}

func run() int {
	// handle config
	isExplicitConfig := false
	// Check if -config was explicitly set (non-empty)
	// flag.NFlag? But default "" means not set or set to ""? If user passes -config="" explicitly, it's still explicit? Treat as explicit if flag was set?
	// Use flag.NFlag and lookup?
	isExplicitConfig = isFlagSet("config")
	var cfg *configFile
	var cfgPath string
	var cfgErr error
	if isExplicitConfig {
		cfg, cfgPath, cfgErr = loadConfig(*flag_config, true)
		_ = cfgPath
		if cfgErr != nil {
			errorLog("ERROR: %s", cfgErr.Error())
			return 1
		}
	} else {
		cfg, cfgPath, cfgErr = loadConfig("", false)
		_ = cfgPath
		_ = cfgErr
		// default missing never errors
	}

	// handle dblist
	if *flag_dblist {
		// need to output db list to stdout
		// if cfg has database, output each "name:driver" in file order
		if cfg != nil && len(cfg.Order) > 0 {
			for _, name := range cfg.Order {
				dc := cfg.Database[name]
				fmt.Printf("%s:%s\n", name, dc.Driver)
			}
		}
		return 0
	}
	// handle -A / -a
	if *flag_A != "" {
		return doAnalyze(*flag_A, true)
	}
	if *flag_a != "" {
		return doAnalyze(*flag_a, false)
	}
	// determine query
	var query string
	if *flag_t != "" {
		query = fmt.Sprintf("SELECT * FROM %s", *flag_t)
	} else if *flag_q != "" {
		data, err := os.ReadFile(*flag_q)
		if err != nil {
			errorLog("ERROR: open %s: no such file or directory", *flag_q)
			return 1
		}
		query = strings.TrimSpace(string(data))
		// If query file has trailing newline, trim? Original? Let's see: query file with newline? It trims? Test: file "SELECT * FROM test.csv\n" should work same.
		// Also if -q and positional both? -q wins, positional ignored (as observed). So ignore flag.Args()
	} else {
		args := flag.Args()
		if len(args) == 0 {
			fmt.Fprint(os.Stderr, helpText)
			return 2
		}
		// join with space
		query = strings.Join(args, " ")
		if strings.TrimSpace(query) == "" {
			fmt.Fprint(os.Stderr, helpText)
			return 2
		}
	}

	// determine driver/dsn
	driver := "sqlite3"
	dsn := ""
	selectedDb := ""
	if cfg != nil && len(cfg.Database) > 0 {
		// log all dbs with > or space (debug only)
		// Determine selected
		if *flag_db != "" {
			selectedDb = *flag_db
		} else if cfg.Db != "" {
			selectedDb = cfg.Db
		}
		// debug log each
		for _, name := range cfg.Order {
			dc := cfg.Database[name]
			if name == selectedDb {
				debugLog(">[driver: %s:%s:%s]", name, dc.Driver, dc.Dsn)
			} else {
				debugLog(" [driver: %s:%s:%s]", name, dc.Driver, dc.Dsn)
			}
		}
		// if selectedDb != "" but not found, error but continue with default?
		if selectedDb != "" {
			if dc, ok := cfg.Database[selectedDb]; ok {
				driver = dc.Driver
				dsn = dc.Dsn
			} else {
				errorLog("ERROR: db[%s] does not found", selectedDb)
				// fall through to default? And also apply -driver/-dsn overrides? Observed: after ERROR, driver becomes default sqlite3 empty, but -driver override still applies? For missing db with -driver? Not tested. Assume overrides apply after.
			}
		} else {
			// no selection, check if -db was specified but missing? Already handled above (selectedDb would be *flag_db, not found => error)
			// if no selection and no -db, driver stays default? Even though config has dbs, without selection, driver is default? Observed: config without db field, with database mydb, no -db => driver sqlite3 empty (default), not mydb. Good.
		}
	} else {
		// no database in config
		if *flag_db != "" {
			// config has no database, but -db specified? What happens? Probably same error db not found?
			// Test: default missing config (no database) with -db missing => ?
			// Let's handle: if *flag_db != "" and no database, error?
			// Need to probe.
			errorLog("ERROR: db[%s] does not found", *flag_db)
		}
	}
	// overrides
	if isFlagSet("driver") {
		driver = *flag_driver
	}
	if isFlagSet("dsn") {
		dsn = *flag_dsn
	}
	// handle driver
	if driver == "mysql" || driver == "postgres" {
		return handleNonSqlite(driver, dsn)
	}
	// sqlite3 or sqlite3_ext or empty? Empty defaults to sqlite3? If driver empty (no config, no -driver), driver is "sqlite3" default? Actually we set default sqlite3. Good.
	// If driver is sqlite3_ext, treat as sqlite3.
	return doQuery(query, driver, dsn)
}

func isFlagSet(name string) bool {
	found := false
	flag.Visit(func(f *flag.Flag) {
		if f.Name == name {
			found = true
		}
	})
	return found
}
GOEOF
cat /workspace/run.go"}

