	cstr := C.CString(v)
	// SQLITE_TRANSIENT = ((sqlite3_destructor_type)-1)
	C.sqlite3_bind_text(stmt, C.int(idx), cstr, -1, C.sqlite3_destructor_type(C.uintptr_t(0xFFFFFFFFFFFFFFFF)))
