			// Actually to match original, we should treat only ' ' as space token, others? But queries rarely contain tabs. We'll just treat any whitespace run? No, original treats each space separately, so we do each char separately.
			if c == ' ' {
				toks = append(toks, " ")
			} else if c == '\t' {
				toks = append(toks, "\t")
			} else if c == '\n' {
				toks = append(toks, "\n")
			} else {
				toks = append(toks, string(c))
			}
			i++
			continue
		}
		// quoted strings: ', ", `
		if c == '\'' || c == '"' || c == '`' {
			quote := c
			j := i + 1
			var sb strings.Builder
			sb.WriteByte(c)
			for j < n {
				if sql[j] == quote {
					// check doubled quote? e.g., '' inside ''? For '' , two single quotes represent escaped? In SQL, '' is escaped single quote. Similarly ""?
					if j+1 < n && sql[j+1] == quote {
						sb.WriteByte(quote)
						sb.WriteByte(quote)
						j += 2
						continue
					}
					sb.WriteByte(quote)
					j++
					break
				}
				sb.WriteByte(sql[j])
				j++
			}
			toks = append(toks, sb.String())
			i = j
			continue
		}
		// delimiters: , ( ) ; = > < !
		// special case <> as one token
		if c == '<' && i+1 < n && sql[i+1] == '>' {
			toks = append(toks, "<>")
			i += 2
			continue
		}
		if c == ',' || c == '(' || c == ')' || c == ';' || c == '=' || c == '>' || c == '<' || c == '!' {
			toks = append(toks, string(c))
			i++
			continue
		}
		// otherwise, accumulate until next delimiter/space/quote
		j := i
		for j < n {
			cc := sql[j]
			if cc == ' ' || cc == '\t' || cc == '\n' || cc == '\r' || cc == '\'' || cc == '"' || cc == '`' || cc == ',' || cc == '(' || cc == ')' || cc == ';' || cc == '=' || cc == '>' || cc == '<' || cc == '!' {
				// check for <>? If cc is < and next is >, we should stop before < to let outer handle <>? Actually our loop would stop at <, then outer will handle <> as one. Good.
				break
			}
			j++
		}
		toks = append(toks, sql[i:j])
		i = j
	}
	return toks
}

func debugTokens(sql string) string {
	toks := tokenize(sql)
	var sb strings.Builder
	for _, t := range toks {
		sb.WriteString("[")
		sb.WriteString(t)
		sb.WriteString("]")
	}
	return sb.String()
}

func isSpaceTok(t string) bool {
	return t == " " || t == "\t" || t == "\n" || t == "\r"
}
