		if (c == '\'' || c == '"' || c == '`') && tok[len(tok)-1] == c {
			return true
		}
	}
	return false
}

type tableRef struct {
	Index int
	Name  string // original token
}

// extract tables with indices
func extractTables(tokens []string) []tableRef {
	var tables []tableRef
	keywords := map[string]bool{
		"from": true, "join": true, "into": true, "update": true, "table": true,
	}
	i := 0
	for i < len(tokens) {
		tok := tokens[i]
		if isSpaceTok(tok) || tok == "," || tok == "(" || tok == ")" || tok == ";" {
			i++
			continue
		}
		lower := strings.ToLower(tok)
		if !isQuoted(tok) && keywords[lower] {
			j := i + 1
			for j < len(tokens) && isSpaceTok(tokens[j]) {
				j++
			}
			if j < len(tokens) {
				t := tokens[j]
				tables = append(tables, tableRef{Index: j, Name: t})
				// comma-separated
				last := j
				pos := j + 1
				for {
					p := pos
					for p < len(tokens) && isSpaceTok(tokens[p]) {
						p++
					}
					if p < len(tokens) && tokens[p] == "," {
						q := p + 1
						for q < len(tokens) && isSpaceTok(tokens[q]) {
							q++
						}
						if q < len(tokens) {
							tables = append(tables, tableRef{Index: q, Name: tokens[q]})
							last = q
							pos = q + 1
							continue
						}
					}
					break
				}
				i = last + 1
				continue
			}
		}
		i++
	}
	return tables
}

func rewriteQuery(tokens []string, tables []tableRef, jqMap map[string]string) string {
	repl := make(map[int]string)
	for _, t := range tables {
		newName := t.Name
		if mapped, ok := jqMap[t.Name]; ok {
			newName = mapped
		}
		repl[t.Index] = "`" + newName + "`"
	}
