package main

import (
	"fmt"
	"strings"
)

func processCSVRecords(db *sqliteDB, table string, records [][]string, readErr error) error {
	skip := *flag_is
	idx := 0
	for i := 0; i < skip && idx < len(records); i++ {
		row := records[idx]
		first := ""
		if len(row) > 0 {
			first = row[0]
		}
		debugLog("Skip row:[%s]", first)
		idx++
	}
	remaining := records[idx:]
	if len(remaining) == 0 {
		return importError{msg: "no rows"}
	}
	var header []string
	var dataRows [][]string
	useHeader := *flag_ih
	if useHeader {
		header = remaining[0]
		if len(remaining) > 1 {
			dataRows = remaining[1:]
		} else {
			dataRows = [][]string{}
		}
	} else {
		dataRows = remaining
	}
	prereadN := *flag_ir
	if prereadN == 0 {
		return importError{msg: "no rows"}
	}
	var colNames []string
	hasInum := *flag_inum
	var prereadRows [][]string
	if useHeader {
		need := prereadN - 1
		if need < 0 {
			need = 0
		}
		if need > len(dataRows) {
			need = len(dataRows)
		}
		prereadRows = dataRows[:need]
		maxCols := len(header)
		for _, r := range prereadRows {
			if len(r) > maxCols {
				maxCols = len(r)
			}
		}
		if maxCols == 0 && len(header) == 0 {
			return importError{msg: "no rows"}
		}
		colNames = make([]string, maxCols)
		for i := 0; i < maxCols; i++ {
			if i < len(header) {
				colNames[i] = header[i]
			} else {
				colNames[i] = fmt.Sprintf("c%d", i+1)
			}
		}
	} else {
		need := prereadN
		if need > len(dataRows) {
			need = len(dataRows)
		}
		if need == 0 {
			return importError{msg: "no rows"}
		}
		prereadRows = dataRows[:need]
		maxCols := 0
		for _, r := range prereadRows {
			if len(r) > maxCols {
				maxCols = len(r)
			}
		}
		if maxCols == 0 {
			return importError{msg: "no rows"}
		}
		colNames = make([]string, maxCols)
		for i := range colNames {
			colNames[i] = fmt.Sprintf("c%d", i+1)
		}
	}
	if hasInum {
		colNames = append([]string{"num"}, colNames...)
	}
	colTypes := make([]string, len(colNames))
	for i := range colTypes {
		if hasInum && i == 0 {
			colTypes[i] = "int"
		} else {
			colTypes[i] = "text"
		}
	}
	debugLog("Column Names: [%s]", strings.Join(colNames, ","))
	debugLog("Column Types: [%s]", strings.Join(colTypes, ","))
	var defs []string
	for i, n := range colNames {
		defs = append(defs, fmt.Sprintf("`%s` %s", n, colTypes[i]))
	}
	createSQL := fmt.Sprintf("CREATE TEMPORARY TABLE `%s` ( %s );", table, strings.Join(defs, ", "))
	if err := db.execWithLog(createSQL); err != nil {
		return importError{msg: err.Error()}
	}
	limit := *flag_ilr
	var rowsToInsert [][]string
	if limit > 0 {
		if limit < len(dataRows) {
			rowsToInsert = dataRows[:limit]
		} else {
			rowsToInsert = dataRows
		}
	} else {
		rowsToInsert = dataRows
	}
	dataColCount := len(colNames)
	if hasInum {
		dataColCount--
	}
	inullVal := string(var_inull)
	hasInull := isFlagSet("inull")
	prereadCount := len(prereadRows)
	if prereadCount > len(rowsToInsert) {
		prereadCount = len(rowsToInsert)
	}
	firstBatch := rowsToInsert[:prereadCount]
	secondBatch := rowsToInsert[prereadCount:]
	logged := make(map[int]bool)
	// helper
	insertOne := func(batch [][]string, startNum int) error {
		if len(batch) == 0 {
			return nil
		}
		placeCount := len(colNames)
		var placeholders []string
		for range batch {
			ph := "(" + strings.TrimRight(strings.Repeat("?,", placeCount), ",") + ")"
			placeholders = append(placeholders, ph)
		}
		var cols []string
		for _, n := range colNames {
			cols = append(cols, fmt.Sprintf("`%s`", n))
		}
		sql := fmt.Sprintf("INSERT INTO `%s` (%s) VALUES %s;", table, strings.Join(cols, ", "), strings.Join(placeholders, ","))
		if !logged[len(batch)] {
			debugLog("%s", sql)
			logged[len(batch)] = true
		}
		stmt, err := db.prepare(sql)
		if err != nil {
			return importError{msg: err.Error()}
		}
		defer finalize(stmt)
		bindIdx := 1
		for i, row := range batch {
			num := startNum + i
			if hasInum {
				bindInt(stmt, bindIdx, num)
				bindIdx++
			}
			padded := make([]string, dataColCount)
			for j := 0; j < dataColCount; j++ {
				if j < len(row) {
					padded[j] = row[j]
				} else {
					padded[j] = ""
				}
			}
			for _, v := range padded {
				if hasInull && v == inullVal {
					bindNull(stmt, bindIdx)
				} else {
					bindText(stmt, bindIdx, v)
				}
				bindIdx++
			}
		}
		rc := stepDone(stmt)
		// SQLITE_DONE = 101
		if rc != 101 {
			return importError{msg: db.errmsg()}
		}
		return nil
	}
	if err := insertOne(firstBatch, 1); err != nil {
		return err
	}
	if err := insertOne(secondBatch, prereadCount+1); err != nil {
		return err
	}
	return nil
}
