	for i, n := range colNames {
		defs = append(defs, fmt.Sprintf("`%s` %s", n, colTypes[i]))
	}
	createSQL := fmt.Sprintf("CREATE TEMPORARY TABLE `%s` ( %s );", table, strings.Join(defs, ", "))
	if err := db.execWithLog(createSQL); err != nil {
		return importError{msg: err.Error()}
	}
	limit := *flag_ilr
	var rowsToInsert [][]string
	if limit > 0 {
		if limit < len(dataRows) {
			rowsToInsert = dataRows[:limit]
		} else {
			rowsToInsert = dataRows
		}
	} else {
		rowsToInsert = dataRows
	}
	dataColCount := len(colNames)
	if hasInum {
		dataColCount--
	}
	inullVal := string(var_inull)
	hasInull := isFlagSet("inull")
	prereadCount := len(prereadRows)
	if prereadCount > len(rowsToInsert) {
		prereadCount = len(rowsToInsert)
	}
	firstBatch := rowsToInsert[:prereadCount]
	secondBatch := rowsToInsert[prereadCount:]
	logged := make(map[int]bool)
	// helper
	insertOne := func(batch [][]string, startNum int) error {
		if len(batch) == 0 {
			return nil
		}
		placeCount := len(colNames)
		var placeholders []string
		for range batch {
			ph := "(" + strings.TrimRight(strings.Repeat("?,", placeCount), ",") + ")"
			placeholders = append(placeholders, ph)
		}
		var cols []string
		for _, n := range colNames {
			cols = append(cols, fmt.Sprintf("`%s`", n))
		}
		sql := fmt.Sprintf("INSERT INTO `%s` (%s) VALUES %s;", table, strings.Join(cols, ", "), strings.Join(placeholders, ","))
		if !logged[len(batch)] {
			debugLog("%s", sql)
			logged[len(batch)] = true
		}
		stmt, err := db.prepare(sql)
		if err != nil {
			return importError{msg: err.Error()}
		}
		defer finalize(stmt)
		bindIdx := 1
		for i, row := range batch {
			num := startNum + i
			if hasInum {
				bindInt(stmt, bindIdx, num)
				bindIdx++
			}
			padded := make([]string, dataColCount)
			for j := 0; j < dataColCount; j++ {
				if j < len(row) {
					padded[j] = row[j]
				} else {
					padded[j] = ""
				}
			}
			for _, v := range padded {
				if hasInull && v == inullVal {
					bindNull(stmt, bindIdx)
				} else {
					bindText(stmt, bindIdx, v)
				}
				bindIdx++
			}
		}
		rc := stepDone(stmt)
		// SQLITE_DONE = 101
		if rc != 101 {
			return importError{msg: db.errmsg()}
		}
		return nil
	}
	if err := insertOne(firstBatch, 1); err != nil {
		return err
	}
	if err := insertOne(secondBatch, prereadCount+1); err != nil {
		return err
	}
	return nil
}
GOEOF
echo done"}

