func compressExternal(tool string, data []byte) ([]byte, error) {
	// tool -c (or -c for bzip2/xz, -c for zstd/lz4?)
	var args []string
	switch tool {
	case "bzip2":
		args = []string{"-c"}
	case "xz":
		args = []string{"-c"}
	case "zstd":
		args = []string{"-c"}
	case "lz4":
		args = []string{"-c"}
	default:
		args = []string{"-c"}
	}
	cmd := exec.Command(tool, args...)
	cmd.Stdin = bytes.NewReader(data)
	var out bytes.Buffer
	cmd.Stdout = &out
	var errBuf bytes.Buffer
	cmd.Stderr = &errBuf
	if err := cmd.Run(); err != nil {
		return nil, err
	}
	return out.Bytes(), nil
}

