package main

import (
	"bytes"
	"fmt"
	"strings"
)

func newCSVWriter(buf *bytes.Buffer, comma rune, useCRLF, allQuotes bool) *csvWriter {
	return &csvWriter{buf: buf, comma: comma, useCRLF: useCRLF, allQuotes: allQuotes}
}

type csvWriter struct {
	buf *bytes.Buffer
	comma rune
	useCRLF bool
	allQuotes bool
}

func (w *csvWriter) Write(rec []string) {
	for i, field := range rec {
		if i > 0 {
			w.buf.WriteRune(w.comma)
		}
		needQuote := w.allQuotes
		if !needQuote {
			// Go csv quoting rules: need quote if field contains comma, quote, \n, \r, or leading space? Actually Go's csv quotes if field contains comma, quote, \n, \r, or leading space? Let's check: earlier test with " 5" (leading space) was quoted as " 5", but "5 " (trailing) was not. So leading space triggers quote, trailing doesn't. Also need quote if field contains delimiter, quote, \n, \r.
			// We'll implement: if field contains comma (delim), quote char, \n, \r, or starts with space, then quote.
			if strings.ContainsRune(field, w.comma) || strings.Contains(field, "\"") || strings.Contains(field, "\n") || strings.Contains(field, "\r") {
				needQuote = true
			} else if len(field) > 0 && field[0] == ' ' {
				needQuote = true
			}
