package main
/*
#cgo LDFLAGS: -lsqlite3
#include <sqlite3.h>
#include <stdlib.h>
*/
import "C"
import (
	"fmt"
	"unsafe"
)

func querySQLite(db *sqliteDB, sql string) ([][]*cell, []string, []string, error) {
	csql := C.CString(sql)
	defer C.free(unsafe.Pointer(csql))
	var stmt *C.sqlite3_stmt
	rc := C.sqlite3_prepare_v2(db.db, csql, -1, &stmt, nil)
	if rc != C.SQLITE_OK {
		return nil, nil, nil, fmt.Errorf("%s", db.errmsg())
	}
	defer C.sqlite3_finalize(stmt)
	ncol := int(C.sqlite3_column_count(stmt))
	colNames := make([]string, ncol)
	for i := 0; i < ncol; i++ {
		cname := C.sqlite3_column_name(stmt, C.int(i))
		if cname != nil {
			colNames[i] = C.GoString(cname)
		}
	}
	colTypes := make([]string, ncol)
	for i := range colTypes {
		colTypes[i] = "text"
	}
	var rows [][]*cell
	for {
		rc = C.sqlite3_step(stmt)
		if rc == C.SQLITE_ROW {
			row := make([]*cell, ncol)
			for i := 0; i < ncol; i++ {
				ct := int(C.sqlite3_column_type(stmt, C.int(i)))
				switch ct {
				case C.SQLITE_NULL:
					row[i] = &cell{isNull: true}
				case C.SQLITE_INTEGER:
					v := int64(C.sqlite3_column_int64(stmt, C.int(i)))
					row[i] = &cell{isInt: true, intVal: v, text: fmt.Sprintf("%d", v)}
				case C.SQLITE_FLOAT:
					v := float64(C.sqlite3_column_double(stmt, C.int(i)))
					row[i] = &cell{isFloat: true, floatVal: v, text: fmt.Sprintf("%v", v)}
				default:
					ctext := C.sqlite3_column_text(stmt, C.int(i))
					if ctext == nil {
						row[i] = &cell{isNull: true}
					} else {
						n := int(C.sqlite3_column_bytes(stmt, C.int(i)))
						s := C.GoStringN((*C.char)(unsafe.Pointer(ctext)), C.int(n))
						row[i] = &cell{text: s}
					}
				}
			}
			rows = append(rows, row)
		} else if rc == C.SQLITE_DONE {
			break
		} else {
			return nil, nil, nil, fmt.Errorf("%s", db.errmsg())
		}
	}
	return rows, colNames, colTypes, nil
}
