				}
				bindIdx++
			}
		}
		rc := stepDone(stmt)
		if rc != 101 {
			return importError{msg: db.errmsg()}
		}
		return nil
	}
	if err := insertOne(firstBatch, 1); err != nil {
		return err
	}
	if err := insertOne(secondBatch, need+1); err != nil {
		return err
	}
	return nil
