	for _, l := range lines {
		trim := strings.TrimSpace(l)
		if trim == "" || strings.HasPrefix(trim, "#") {
			continue
		}
		if strings.HasPrefix(trim, "- ") || trim == "-" {
			isList = true
		}
		break
	}
	var rows []map[string]string
	var order []string
	if isList {
		var cur map[string]string
		var curOrder []string
		for _, line := range lines {
			trim := strings.TrimSpace(line)
			if trim == "" || strings.HasPrefix(trim, "#") {
				continue
			}
			if strings.HasPrefix(trim, "- ") || trim == "-" {
				if cur != nil {
