					v := strings.TrimSpace(trim[pos+1:])
					v = stripYAMLValue(v)
					cur[k] = v
					curOrder = append(curOrder, k)
				}
			}
		}
		if cur != nil {
			rows = append(rows, cur)
			for _, k := range curOrder {
				if !contains(order, k) {
					order = append(order, k)
				}
			}
		}
	} else {
		hasColon := false
		for _, l := range lines {
			if strings.Contains(l, ":") {
				hasColon = true
				break
			}
		}
		if hasColon {
			m := make(map[string]string)
			var o []string
			for _, l := range lines {
				trim := strings.TrimSpace(l)
				if trim == "" || strings.HasPrefix(trim, "#") {
					continue
				}
				if pos := strings.Index(trim, ":"); pos >= 0 {
					k := strings.TrimSpace(trim[:pos])
					v := strings.TrimSpace(trim[pos+1:])
					v = stripYAMLValue(v)
					m[k] = v
					o = append(o, k)
				}
			}
			rows = append(rows, m)
			order = o
		} else {
			for _, l := range lines {
				trim := strings.TrimSpace(l)
				if trim == "" {
					continue
				}
				m := map[string]string{"c1": trim}
				rows = append(rows, m)
			}
			order = []string{"c1"}
		}
	}
	return rows, order
}
